use clap::{Parser, Subcommand};
use std::net::SocketAddr;
use tokio::io::{AsyncReadExt, AsyncWriteExt};
use tokio::net::{TcpListener, TcpStream};
use anyhow::Result;

#[derive(Parser)]
#[command(version = "bore-cli 0.6.0")]
#[command(about = "A modern, simple TCP tunnel in Rust that exposes local ports to a remote server, bypassing standard NAT connection firewalls.", long_about = None)]
struct Cli {
    #[command(subcommand)]
    command: Commands,
}

#[derive(Subcommand)]
enum Commands {
    /// Starts a local proxy to the remote server
    Local {
        /// The local port to expose
        #[arg(env = "BORE_LOCAL_PORT")]
        local_port: u16,

        /// The local host to expose
        #[arg(short, long, default_value = "localhost")]
        local_host: String,

        /// Address of the remote server to expose local ports to
        #[arg(short, long, env = "BORE_SERVER")]
        to: String,

        /// Optional port on the remote server to select
        #[arg(short, default_value = "0")]
        port: u16,

        /// Optional secret for authentication
        #[arg(short, env = "BORE_SECRET")]
        secret: Option<String>,
    },

    /// Runs the remote proxy server
    Server {
        /// Minimum accepted TCP port number
        #[arg(long, env = "BORE_MIN_PORT", default_value = "1024")]
        min_port: u16,

        /// Maximum accepted TCP port number
        #[arg(long, env = "BORE_MAX_PORT", default_value = "65535")]
        max_port: u16,

        /// Optional secret for authentication
        #[arg(short, env = "BORE_SECRET")]
        secret: Option<String>,

        /// IP address to bind to, clients must reach this
        #[arg(long, default_value = "0.0.0.0")]
        bind_addr: String,

        /// IP address where tunnels will listen on, defaults to --bind-addr
        #[arg(long)]
        bind_tunnels: Option<String>,
    },
}

#[tokio::main]
async fn main() -> Result<()> {
    let cli = Cli::parse();

    match cli.command {
        Commands::Local {
            local_port,
            local_host,
            to,
            port,
            secret,
        } => {
            run_local(local_host, local_port, to, port, secret).await?;
        }
        Commands::Server {
            min_port,
            max_port,
            secret,
            bind_addr,
            bind_tunnels,
        } => {
            let bind_tunnels = bind_tunnels.unwrap_or_else(|| bind_addr.clone());
            run_server(bind_addr, bind_tunnels, min_port, max_port, secret).await?;
        }
    }

    Ok(())
}

async fn run_local(
    local_host: String,
    local_port: u16,
    server_addr: String,
    remote_port: u16,
    secret: Option<String>,
) -> Result<()> {
    println!("Starting local tunnel...");
    Ok(())
}

async fn run_server(
    bind_addr: String,
    bind_tunnels: String,
    min_port: u16,
    max_port: u16,
    secret: Option<String>,
) -> Result<()> {
    println!("Starting server...");
    Ok(())
}
