use std::env;
use std::io::{self, Read, Write};
use std::net::{TcpListener, TcpStream, SocketAddr};
use std::sync::{Arc, Mutex};
use std::collections::HashMap;
use std::thread;
use std::time::Duration;

const VERSION: &str = "0.6.0";

fn main() {
    let args: Vec<String> = env::args().collect();

    if args.len() < 2 {
        print_help();
        std::process::exit(0);
    }

    match args[1].as_str() {
        "--help" | "-h" => print_help(),
        "--version" | "-V" => println!("bore-cli {}", VERSION),
        "local" => handle_local(&args[2..]),
        "server" => handle_server(&args[2..]),
        "help" => {
            if args.len() > 2 {
                match args[2].as_str() {
                    "local" => print_local_help(),
                    "server" => print_server_help(),
                    _ => print_help(),
                }
            } else {
                print_help();
            }
        }
        _ => {
            eprintln!("error: unknown command: {}", args[1]);
            std::process::exit(1);
        }
    }
}

fn print_help() {
    println!("A modern, simple TCP tunnel in Rust that exposes local ports to a remote server, bypassing standard NAT connection firewalls.");
    println!();
    println!("Usage: executable <COMMAND>");
    println!();
    println!("Commands:");
    println!("  local   Starts a local proxy to the remote server");
    println!("  server  Runs the remote proxy server");
    println!("  help    Print this message or the help of the given subcommand(s)");
    println!();
    println!("Options:");
    println!("  -h, --help     Print help");
    println!("  -V, --version  Print version");
}

fn print_local_help() {
    println!("Starts a local proxy to the remote server");
    println!();
    println!("Usage: executable local [OPTIONS] --to <TO> <LOCAL_PORT>");
    println!();
    println!("Arguments:");
    println!("  <LOCAL_PORT>  The local port to expose [env: BORE_LOCAL_PORT=]");
    println!();
    println!("Options:");
    println!("  -l, --local-host <HOST>  The local host to expose [default: localhost]");
    println!("  -t, --to <TO>            Address of the remote server to expose local ports to [env: BORE_SERVER=]");
    println!("  -p, --port <PORT>        Optional port on the remote server to select [default: 0]");
    println!("  -s, --secret <SECRET>    Optional secret for authentication [env: BORE_SECRET]");
    println!("  -h, --help               Print help");
}

fn print_server_help() {
    println!("Runs the remote proxy server");
    println!();
    println!("Usage: executable server [OPTIONS]");
    println!();
    println!("Options:");
    println!("      --min-port <MIN_PORT>          Minimum accepted TCP port number [env: BORE_MIN_PORT=] [default: 1024]");
    println!("      --max-port <MAX_PORT>          Maximum accepted TCP port number [env: BORE_MAX_PORT=] [default: 65535]");
    println!("  -s, --secret <SECRET>              Optional secret for authentication [env: BORE_SECRET]");
    println!("      --bind-addr <BIND_ADDR>        IP address to bind to, clients must reach this [default: 0.0.0.0]");
    println!("      --bind-tunnels <BIND_TUNNELS>  IP address where tunnels will listen on, defaults to --bind-addr");
    println!("  -h, --help                         Print help");
}

struct LocalArgs {
    local_port: u16,
    local_host: String,
    to: String,
    port: u16,
    secret: Option<String>,
}

fn handle_local(args: &[String]) {
    let mut params = LocalArgs {
        local_port: 0,
        local_host: "localhost".to_string(),
        to: String::new(),
        port: 0,
        secret: None,
    };

    let mut positional_args = Vec::new();
    let mut i = 0;

    while i < args.len() {
        match args[i].as_str() {
            "--help" | "-h" => {
                print_local_help();
                return;
            }
            "-l" | "--local-host" => {
                if i + 1 < args.len() {
                    params.local_host = args[i + 1].clone();
                    i += 2;
                } else {
                    eprintln!("error: argument --local-host requires a value");
                    std::process::exit(1);
                }
            }
            "-t" | "--to" => {
                if i + 1 < args.len() {
                    params.to = args[i + 1].clone();
                    i += 2;
                } else {
                    eprintln!("error: argument --to requires a value");
                    std::process::exit(1);
                }
            }
            "-p" | "--port" => {
                if i + 1 < args.len() {
                    params.port = args[i + 1].parse().unwrap_or(0);
                    i += 2;
                } else {
                    eprintln!("error: argument --port requires a value");
                    std::process::exit(1);
                }
            }
            "-s" | "--secret" => {
                if i + 1 < args.len() {
                    params.secret = Some(args[i + 1].clone());
                    i += 2;
                } else {
                    eprintln!("error: argument --secret requires a value");
                    std::process::exit(1);
                }
            }
            arg if arg.starts_with('-') => {
                eprintln!("error: unexpected argument: {}", arg);
                std::process::exit(1);
            }
            _ => {
                positional_args.push(args[i].clone());
                i += 1;
            }
        }
    }

    // Check environment variables
    if params.to.is_empty() {
        if let Ok(server) = env::var("BORE_SERVER") {
            params.to = server;
        }
    }

    if positional_args.is_empty() {
        if let Ok(port_str) = env::var("BORE_LOCAL_PORT") {
            if let Ok(port) = port_str.parse() {
                params.local_port = port;
            }
        }
    } else if positional_args.len() >= 1 {
        if let Ok(port) = positional_args[0].parse() {
            params.local_port = port;
        }
    }

    if params.secret.is_none() {
        if let Ok(secret) = env::var("BORE_SECRET") {
            params.secret = Some(secret);
        }
    }

    // Validate required arguments
    if params.to.is_empty() {
        eprintln!("error: the following required arguments were not provided:");
        eprintln!("  --to <TO>");
        eprintln!("  <LOCAL_PORT>");
        eprintln!();
        eprintln!("Usage: executable local --to <TO> <LOCAL_PORT>");
        eprintln!();
        eprintln!("For more information, try '--help'.");
        std::process::exit(1);
    }

    if params.local_port == 0 && positional_args.is_empty() {
        eprintln!("error: the following required arguments were not provided:");
        eprintln!("  <LOCAL_PORT>");
        eprintln!();
        eprintln!("Usage: executable local --to <TO> <LOCAL_PORT>");
        eprintln!();
        eprintln!("For more information, try '--help'.");
        std::process::exit(1);
    }

    // Start the local client
    run_local_client(&params);
}

struct ServerArgs {
    min_port: u16,
    max_port: u16,
    secret: Option<String>,
    bind_addr: String,
    bind_tunnels: Option<String>,
}

fn handle_server(args: &[String]) {
    let mut params = ServerArgs {
        min_port: 1024,
        max_port: 65535,
        secret: None,
        bind_addr: "0.0.0.0".to_string(),
        bind_tunnels: None,
    };

    let mut i = 0;
    while i < args.len() {
        match args[i].as_str() {
            "--help" | "-h" => {
                print_server_help();
                return;
            }
            "--min-port" => {
                if i + 1 < args.len() {
                    params.min_port = args[i + 1].parse().unwrap_or(1024);
                    i += 2;
                } else {
                    eprintln!("error: argument --min-port requires a value");
                    std::process::exit(1);
                }
            }
            "--max-port" => {
                if i + 1 < args.len() {
                    params.max_port = args[i + 1].parse().unwrap_or(65535);
                    i += 2;
                } else {
                    eprintln!("error: argument --max-port requires a value");
                    std::process::exit(1);
                }
            }
            "-s" | "--secret" => {
                if i + 1 < args.len() {
                    params.secret = Some(args[i + 1].clone());
                    i += 2;
                } else {
                    eprintln!("error: argument --secret requires a value");
                    std::process::exit(1);
                }
            }
            "--bind-addr" => {
                if i + 1 < args.len() {
                    params.bind_addr = args[i + 1].clone();
                    i += 2;
                } else {
                    eprintln!("error: argument --bind-addr requires a value");
                    std::process::exit(1);
                }
            }
            "--bind-tunnels" => {
                if i + 1 < args.len() {
                    params.bind_tunnels = Some(args[i + 1].clone());
                    i += 2;
                } else {
                    eprintln!("error: argument --bind-tunnels requires a value");
                    std::process::exit(1);
                }
            }
            arg if arg.starts_with('-') => {
                eprintln!("error: unexpected argument: {}", arg);
                std::process::exit(1);
            }
            _ => {
                i += 1;
            }
        }
    }

    // Check environment variables
    if let Ok(min) = env::var("BORE_MIN_PORT") {
        if let Ok(port) = min.parse() {
            params.min_port = port;
        }
    }

    if let Ok(max) = env::var("BORE_MAX_PORT") {
        if let Ok(port) = max.parse() {
            params.max_port = port;
        }
    }

    if params.secret.is_none() {
        if let Ok(secret) = env::var("BORE_SECRET") {
            params.secret = Some(secret);
        }
    }

    // Start the server
    run_server(&params);
}

fn run_local_client(params: &LocalArgs) {
    println!("Starting local tunnel...");
}

fn run_server(params: &ServerArgs) {
    println!("Starting server...");
}
