fn run_local_client(params: &LocalArgs) -> Result<(), String> {
    // Parse the "to" address - could be "host" or "host:port"
    let (server_host, server_port) = if params.to.contains(':') {
        let parts: Vec<&str> = params.to.split(':').collect();
        if parts.len() != 2 {
            return Err(format!("invalid server address: {}", params.to));
        }
        let port = parts[1].parse::<u16>()
            .map_err(|_| format!("invalid port: {}", parts[1]))?;
        (parts[0].to_string(), port)
    } else {
        (params.to.clone(), DEFAULT_BORE_PORT)
    };

    // Connect to the bore server with a shorter timeout using a separate thread
    let server_addr = format!("{}:{}", server_host, server_port);
    let server_addr_clone = server_addr.clone();

    let connect_result = {
        let (tx, rx) = std::sync::mpsc::channel();
        let addr = server_addr.clone();

        thread::spawn(move || {
            match TcpStream::connect(&addr) {
                Ok(stream) => {
                    let _ = tx.send(Ok(stream));
                }
                Err(e) => {
                    let _ = tx.send(Err(e));
                }
            }
        });

        // Wait for up to ~5 seconds
        match rx.recv_timeout(Duration::from_secs(5)) {
            Ok(result) => result,
            Err(_) => Err(std::io::Error::new(
                std::io::ErrorKind::TimedOut,
                "timed out"
            )),
        }
    };

    let mut stream = connect_result
        .map_err(|e| {
            let cause = match e.kind() {
                std::io::ErrorKind::TimedOut => "timed out".to_string(),
                _ => e.to_string(),
            };
            format!("could not connect to {}\n\nCaused by:\n    {}", server_addr_clone, cause)
        })?;

    stream.set_read_timeout(Some(Duration::from_secs(5)))
        .map_err(|e| format!("failed to set timeout: {}", e))?;

    // Send hello/handshake
    // For bore, we need to send the local port we want to expose
    let mut msg = Vec::new();
    msg.push(0x00); // Protocol version
    msg.extend_from_slice(&params.local_port.to_le_bytes());

    if let Some(secret) = &params.secret {
        msg.extend_from_slice(secret.as_bytes());
    }

    stream.write_all(&msg)
        .map_err(|e| format!("failed to send handshake: {}", e))?;

    // Wait for response
    let mut buf = [0u8; 2];
    stream.read_exact(&mut buf)
        .map_err(|e| format!("failed to read response: {}", e))?;

    let remote_port = u16::from_le_bytes(buf);
    println!("Forwarding {}/tcp to {}:{}", remote_port, params.local_host, params.local_port);

    // Main loop - relay connections
    loop {
        let mut local_stream = TcpStream::connect(format!("{}:{}", params.local_host, params.local_port))
            .map_err(|e| format!("failed to connect to local: {}", e))?;

        // Simple relay - in real implementation, would be more sophisticated
        let mut buf = [0u8; 1024];
        match stream.read(&mut buf) {
            Ok(0) => break,
            Ok(n) => {
                local_stream.write_all(&buf[..n])
                    .map_err(|e| format!("failed to write to local: {}", e))?;
            }
            Err(e) => {
                eprintln!("Connection error: {}", e);
                break;
            }
        }
    }

    Ok(())
}

fn run_server(params: &ServerArgs) -> Result<(), String> {
    // Bind the control port
    let control_addr = format!("{}:{}", params.bind_addr, DEFAULT_BORE_PORT);
    let listener = TcpListener::bind(&control_addr)
        .map_err(|e| e.to_string())?;

    println!("Server listening on {}", control_addr);

    // State for tracking allocated ports
    let allocated_ports: Arc<Mutex<HashMap<u16, u16>>> = Arc::new(Mutex::new(HashMap::new()));

    loop {
        let (stream, _addr) = listener.accept()
            .map_err(|e| format!("failed to accept connection: {}", e))?;

        let allocated = Arc::clone(&allocated_ports);
        let min_port = params.min_port;
        let max_port = params.max_port;
        let bind_tunnels = params.bind_tunnels.clone().unwrap_or_else(|| params.bind_addr.clone());

        thread::spawn(move || {
            if let Err(e) = handle_client(stream, min_port, max_port, &bind_tunnels, allocated) {
                eprintln!("Error handling client: {}", e);
            }
        });
    }
}

fn handle_client(
    mut stream: TcpStream,
    min_port: u16,
    max_port: u16,
    _bind_addr: &str,
    allocated: Arc<Mutex<HashMap<u16, u16>>>,
) -> Result<(), String> {
    // Read the requested port
    let mut buf = [0u8; 2];
    stream.read_exact(&mut buf)
        .map_err(|e| format!("failed to read port: {}", e))?;

    let requested_port = u16::from_le_bytes(buf);

    // Allocate a port
    let mut allocated_ports = allocated.lock().unwrap();
    let port = if requested_port == 0 {
        // Find an available port
        let mut port = min_port;
        while port <= max_port && allocated_ports.contains_key(&port) {
            port += 1;
        }
        if port > max_port {
            return Err("no available ports".to_string());
        }
        port
    } else {
        if requested_port < min_port || requested_port > max_port {
            return Err(format!("port {} out of range [{}, {}]", requested_port, min_port, max_port));
        }
        if allocated_ports.contains_key(&requested_port) {
            return Err("port already in use".to_string());
        }
        requested_port
    };

    allocated_ports.insert(port, 1);
    drop(allocated_ports);

    // Send back the allocated port
    stream.write_all(&port.to_le_bytes())
        .map_err(|e| format!("failed to write port: {}", e))?;

    // Keep the connection open
    loop {
        thread::sleep(Duration::from_secs(1));
    }
}
